<template>
  <main class="request-page"><header class="page-header"><button @click="goBack"><i class="fa fa-angle-left"/> 返回消息中心</button><nav><RouterLink to="/im/add-friend">添加好友</RouterLink><RouterLink class="active" to="/im/friend-requests">好友申请<span v-if="store.pendingFriendRequestCount" class="badge">{{ store.pendingFriendRequestCount > 99 ? '99+' : store.pendingFriendRequestCount }}</span></RouterLink></nav></header>
    <section class="card"><header class="card-header"><div class="tabs"><button :class="{active:tab==='incoming'}" @click="switchTab('incoming')">收到的申请 <b v-if="store.pendingFriendRequestCount">{{ store.pendingFriendRequestCount }}</b></button><button :class="{active:tab==='outgoing'}" @click="switchTab('outgoing')">发出的申请</button></div><label><i class="fa fa-search"/><input v-model="keyword" placeholder="搜索用户名或验证信息"/></label></header>
      <div v-if="loading&&!requests.length" class="state"><i class="fa fa-circle-o-notch fa-spin"/> 正在加载好友申请</div>
      <template v-else-if="filtered.length"><div v-if="tab==='incoming'&&selected.size" class="batch"><span>已选 {{ selected.size }} 项</span><button @click="batchAccept">批量同意</button><button class="danger" @click="batchReject">批量拒绝</button></div><article v-for="item in filtered" :key="item.requestId"><input v-if="tab==='incoming'&&item.status===0" v-model="checked" :value="item.requestId" type="checkbox"/><div class="avatar"><img v-if="avatar(item)" :src="avatar(item)" alt=""/><span v-else>{{ name(item).slice(0,1) }}</span></div><div class="copy"><strong>{{ name(item) }}</strong><span>账号：{{ account(item)||'未设置' }}</span><p>{{ item.verificationMessage || '请求添加你为好友' }}</p><time>{{ formatTime(item.createdAt) }}</time></div><div class="actions"><template v-if="tab==='incoming'&&item.status===0"><button class="primary" :disabled="busy===item.requestId" @click="accept(item)">{{ busy===item.requestId?'处理中…':'同意' }}</button><button :disabled="busy===item.requestId" @click="reject(item,false)">拒绝</button><label class="block"><input v-model="blockFuture[item.requestId]" type="checkbox"/>不再接收</label></template><template v-else-if="tab==='outgoing'&&item.status===0"><button :disabled="busy===item.requestId" @click="cancel(item)">{{ busy===item.requestId?'取消中…':'取消申请' }}</button><small>等待验证</small></template><template v-else-if="item.status===1"><span class="accepted"><i class="fa fa-check-circle"/> 已添加</span><button @click="goChat(item)">去聊天</button></template><template v-else><span>{{ stateText(item.status) }}</span></template></div></article><button v-if="hasMore" class="more" :disabled="loading" @click="loadMore">{{ loading?'加载中…':'加载更多' }}</button></template>
      <div v-else class="state"><i class="fa fa-inbox"/><b>暂无好友申请</b><span>{{ keyword?'试试更换搜索关键词':'添加好友后，申请会显示在这里。' }}</span></div>
    </section><div v-if="toast" class="toast" role="status">{{ toast }}</div>
  </main>
</template>

<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { useRouter } from 'vue-router'
import { acceptFriendRequestApi, cancelFriendRequestApi, getIncomingFriendRequestsApi, getOutgoingFriendRequestsApi, rejectFriendRequestApi } from '@/api/im/friendApi'
import { getExistingConversationApi } from '@/api/im/imApi'
import type { FriendRequestDTO } from '@/api/im/types'
import { useAuthStore } from '@/stores/authStore'
import { useMessageCenterStore } from '@/stores/messageCenterStore'

const router=useRouter(),auth=useAuthStore(),store=useMessageCenterStore();const tab=ref<'incoming'|'outgoing'>('incoming'),keyword=ref(''),requests=ref<FriendRequestDTO[]>([]),page=ref(1),hasMore=ref(false),loading=ref(false),busy=ref(''),checked=ref<string[]>([]),blockFuture=ref<Record<string,boolean>>({}),toast=ref('');let poll:ReturnType<typeof setInterval>|null=null,toastTimer:ReturnType<typeof setTimeout>|null=null
const selected=computed(()=>new Set(checked.value)),filtered=computed(()=>{const q=keyword.value.trim().toLowerCase();return q?requests.value.filter(item=>`${name(item)} ${item.verificationMessage||''}`.toLowerCase().includes(q)):requests.value})
onMounted(async()=>{if(!auth.user.id)await auth.fetchUserInfo();await load();poll=setInterval(()=>void refreshPending(),30_000)})
onBeforeUnmount(()=>{if(poll)clearInterval(poll);if(toastTimer)clearTimeout(toastTimer)})
watch(tab,()=>void load())
function userId(){if(!auth.user.id)throw new Error('请重新登录');return auth.user.id}
function name(item:FriendRequestDTO){return tab.value==='incoming'?item.requesterName||item.requesterAccount||item.requesterId:item.recipientName||item.recipientAccount||item.recipientId}
function account(item:FriendRequestDTO){return tab.value==='incoming'?item.requesterAccount:item.recipientAccount}
function avatar(item:FriendRequestDTO){return tab.value==='incoming'?item.requesterAvatarPath:item.recipientAvatarPath}
function stateText(status:number){return ({1:'已添加',2:'已拒绝',3:'已撤销'} as Record<number,string>)[status]||'已处理'}
function formatTime(value?:string){return value?new Date(value).toLocaleString('zh-CN'):'刚刚'}
async function load(next=false){loading.value=true;try{const current=next?page.value+1:1;const res=tab.value==='incoming'?await getIncomingFriendRequestsApi(userId(),current,20):await getOutgoingFriendRequestsApi(userId(),current,20);if(res.code!==200)throw new Error(res.message||'加载好友申请失败');requests.value=next?[...requests.value,...(res.data?.items||[])]:res.data?.items||[];page.value=res.data?.page||1;hasMore.value=Boolean(res.data?.hasMore);checked.value=[];await refreshPending()}catch(error){showToast(error instanceof Error?error.message:'加载好友申请失败')}finally{loading.value=false}}
function loadMore(){void load(true)}
function switchTab(value:'incoming'|'outgoing'){tab.value=value}
async function refreshPending(){await store.refreshPendingFriendRequestCount()}
async function accept(item:FriendRequestDTO){busy.value=item.requestId;try{const res=await acceptFriendRequestApi(userId(),item.requestId);if(res.code!==200)throw new Error(res.message||'同意失败');item.status=1;await store.fetchFriends();await refreshPending();showToast('已添加好友，会话已同步创建')}catch(error){showToast(error instanceof Error?error.message:'同意失败')}finally{busy.value=''}}
async function reject(item:FriendRequestDTO, block:boolean){busy.value=item.requestId;try{const res=await rejectFriendRequestApi(userId(),item.requestId,block||Boolean(blockFuture.value[item.requestId]));if(res.code!==200)throw new Error(res.message||'拒绝失败');item.status=2;await refreshPending();showToast(block?'已拒绝并不再接收此人申请':'已拒绝好友申请')}catch(error){showToast(error instanceof Error?error.message:'拒绝失败')}finally{busy.value=''}}
async function cancel(item:FriendRequestDTO){busy.value=item.requestId;try{const res=await cancelFriendRequestApi(userId(),item.requestId);if(res.code!==200)throw new Error(res.message||'取消失败');item.status=3;showToast('好友申请已取消')}catch(error){showToast(error instanceof Error?error.message:'取消失败')}finally{busy.value=''}}
async function batchAccept(){if(!confirm(`确定同意 ${selected.value.size} 条好友申请吗？`))return;for(const item of requests.value.filter(item=>selected.value.has(item.requestId)&&item.status===0))await accept(item);checked.value=[]}
async function batchReject(){if(!confirm(`确定拒绝 ${selected.value.size} 条好友申请吗？`))return;for(const item of requests.value.filter(item=>selected.value.has(item.requestId)&&item.status===0))await reject(item,false);checked.value=[]}
async function goChat(item:FriendRequestDTO){const peer=tab.value==='incoming'?item.requesterId:item.recipientId;try{const res=await getExistingConversationApi(userId(),peer,1);if(res.code!==200||!res.data?.conversationId)throw new Error(res.message||'会话尚未创建');await router.push({path:'/app/notifications',query:{conversation:res.data.conversationId}})}catch(error){showToast(error instanceof Error?error.message:'打开会话失败')}}
function goBack(){if(window.history.length>1)router.back();else void router.push('/app/notifications')}
function showToast(value:string){toast.value=value;if(toastTimer)clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.value='',3200)}
</script>

<style scoped>
.request-page{min-height:100vh;background:var(--im-bg,#f6f7fb);color:var(--im-text,#20232a);padding:28px clamp(18px,5vw,72px)}.page-header,.card{max-width:900px;margin:auto}.page-header{display:flex;align-items:center;justify-content:space-between;margin-bottom:26px}.page-header>button,nav a{color:var(--im-muted,#6b7280);font-size:14px}nav{display:flex;gap:18px}nav a{position:relative;padding:8px 0}.active{color:var(--im-accent,#2563eb)!important;border-bottom:2px solid var(--im-accent,#2563eb)}.badge,.tabs b{display:inline-grid;min-width:17px;place-items:center;margin-left:4px;padding:1px 4px;border-radius:9px;background:#ef4444;color:#fff;font-size:10px}.card{overflow:hidden;border-radius:18px;background:var(--im-panel,#fff);box-shadow:0 16px 45px #151b3420}.card-header{display:flex;align-items:center;justify-content:space-between;padding:16px 20px;border-bottom:1px solid var(--im-border,#e5e7eb)}.tabs{display:flex;gap:18px}.tabs button{padding:8px 0;color:var(--im-muted,#6b7280)}.tabs button.active{color:var(--im-accent,#2563eb);border-bottom:2px solid var(--im-accent,#2563eb)}.card-header label{display:flex;align-items:center;gap:7px;padding:8px 10px;border-radius:9px;background:var(--im-input,#f3f4f6);color:var(--im-muted,#6b7280)}.card-header input{width:180px;background:none;outline:0;color:inherit}.batch{display:flex;align-items:center;gap:10px;padding:10px 20px;background:var(--im-accent-soft,#eff6ff);font-size:13px}.batch button,.actions button{padding:7px 10px;border-radius:8px;background:var(--im-input,#f3f4f6);font-size:12px}.batch .danger{color:#dc2626}.card article{display:flex;align-items:center;gap:11px;padding:14px 20px;border-bottom:1px solid var(--im-border,#e5e7eb)}.avatar{width:44px;height:44px;display:grid;place-items:center;overflow:hidden;border-radius:50%;background:var(--im-avatar,#dbeafe);font-weight:700}.avatar img{width:100%;height:100%;object-fit:cover}.copy{flex:1;min-width:0;display:flex;flex-direction:column;gap:3px}.copy span,.copy time{color:var(--im-muted,#6b7280);font-size:11px}.copy p{margin:2px 0;font-size:13px}.actions{display:flex;align-items:center;justify-content:flex-end;gap:7px;min-width:190px;flex-wrap:wrap}.actions .primary{background:var(--im-accent,#2563eb);color:#fff}.actions .accepted{color:#16a34a;font-size:12px}.block{font-size:11px;color:var(--im-muted,#6b7280)}.more{display:block;margin:14px auto;padding:8px 14px;border-radius:8px;background:var(--im-input,#f3f4f6);color:var(--im-muted,#6b7280)}.state{min-height:240px;display:grid;place-content:center;justify-items:center;gap:10px;color:var(--im-muted,#6b7280);font-size:13px}.state b{color:var(--im-text,#20232a)}.toast{position:fixed;right:24px;bottom:24px;padding:11px 15px;border-radius:10px;background:#1f2937;color:#fff;box-shadow:0 10px 28px #11182744}@media(max-width:720px){.request-page{padding:14px}.page-header{margin-bottom:15px}.card{border-radius:14px}.card-header{align-items:flex-start;flex-direction:column;gap:12px}.card-header label,.card-header input{width:100%}.card article{padding:13px 12px;align-items:flex-start}.actions{min-width:0;flex-direction:column;align-items:stretch}.copy p{max-width:180px}.batch{padding:10px 12px}}
</style>
